{"query":"query FetchProductCollection($id: String, $country: String!, $currencyCode: CurrencyCode!, $limit: Int!, $marketName: String, $page: Int!) {
  productCollection(id: $id) {
    tileType
    priceType
    footnotesType
    trackingEvent
    helpMessage
    ...ResultsFragment
    seeAllCTA {
      title
      url
      urlType
    }
    title
  }
}

fragment ResultsFragment on ProductCollection {
  results(page: $page, limit: $limit) {
    edges {
      isAd
      adIdentifier
      adInventoryId
      adInventoryType
      node {
        ... on Product {
          ...HomeProductDetailsFragment
        }
        ... on Variant {
          __typename
          id
          sizeChart {
            baseSize
            baseType
            displayOptions {
              size
              type
            }
          }
          product {
            ...HomeProductDetailsFragment
          }
          market(currencyCode: $currencyCode) {
            ...HomeMarketFragment
          }
          ...FavoriteVariantFragment
        }
      }
    }
    pageInfo {
      total
    }
  }
}

fragment HomeProductDetailsFragment on Product {
  __typename
  id
  title
  brand
  browseVerticals
  gender
  productCategory
  categories {
    default {
      alias
    }
  }
  primaryCategory
  listingType
  name
  urlKey
  uuid
  sizeDescriptor
  ...FavoriteProductFragment
  variants {
    id
  }
  media {
    smallImageUrl
  }
  market(currencyCode: $currencyCode) {
    state(country: $country, market: $marketName) {
      askServiceLevels {
        expressExpedited {
          count
          lowest {
            amount
          }
        }
        expressStandard {
          count
          lowest {
            amount
          }
        }
      }
    }
    ...HomeMarketFragment
  }
  traits(filterTypes: [RELEASE_DATE, RETAIL_PRICE]) {
    name
    value
  }
}

fragment HomeMarketFragment on Market {
  currencyCode
  state(country: $country, market: $marketName) {
    highestBid {
      amount
      updatedAt
    }
    lowestAsk {
      amount
      updatedAt
    }
    askServiceLevels {
      expressExpedited {
        lowest {
          amount
        }
      }
      expressStandard {
        lowest {
          amount
        }
      }
    }
  }
  statistics {
    lastSale {
      amount
    }
    last72Hours {
      salesCount
    }
    annual {
      salesCount
    }
    last90Days {
      averagePrice
    }
  }
}

fragment FavoriteProductFragment on Product {
  favorite
}

