{"query":"query GetSellProduct($id: String!, $currencyCode: CurrencyCode, $country: String!, $market: String, $originCountry: String, $originRegion: String, $guidanceEligible: Boolean!) {
  product(id: $id) {
    id
    urlKey
    primaryCategory
    productCategory
    gender
    brand
    styleId
    listingType
    ...ProductHero
    title
    browseVerticals
    contentGroup
    minimumBid(currencyCode: $currencyCode)
    hazardousMaterial {
      lithiumIonBucket
    }
    availableSizeConversions {
      name
      type
    }
    ...ProductTradePolicy
    ...Variants
    ...Shipping
    variants {
      id
      traits {
        size
        sizeDescriptor
      }
      sizeChart {
        baseSize
      }
      pricingGuidance(currencyCode: $currencyCode, country: $country, market: $market) @include(if: $guidanceEligible) {
        sellingGuidance {
          earnMore
          sellFaster
        }
      }
    }
    sizeDescriptor
    sizeAllDescriptor
    traits {
      name
      value
    }
  }
}

