      shortCode
    }
    traits {
      size
    }
    sizeChart {
      baseSize
      baseType
      displayOptions {
        size
        type
      }
    }
    market(currencyCode: $currencyCode) {
      statistics {
        lastSale {
          amount
        }
        last90Days {
          averagePrice
        }
      }
      state(country: $country, market: $market) {
        numberOfAsks
